    original_amount, original_currency, category, subcategory, auto_classified,
    summary, description, counterparty, raw_json
)
SELECT
    sr.id,
    (SELECT id FROM import_row),
    sr.source_uid,
    'ccb_debit_7332_20260622',
    'CCB',
    'ccb_7332',
    'debit',
    sr.transaction_date,
    sr.transaction_date,
    sr.amount,
    sr.currency,
    sr.balance,
    sr.original_amount,
    sr.original_currency,
    sr.category,
    sr.subcategory,
    sr.auto_classified,
    sr.summary,
    sr.description,
    sr.counterparty,
    sr.raw_json
FROM statement_rows sr
ON CONFLICT (source_uid) DO UPDATE
SET import_id = EXCLUDED.import_id,
